def process(wildfires) -> pd.DataFrame:
    import pandas as pd
    import numpy as np

    df = wildfires.copy()

    # Normalize likely column names
    cols = {c.lower(): c for c in df.columns}

    # Month column: prefer 'month' else parse from date-like column
    month_col = None
    for key in ['month', 'mon']:
        if key in cols:
            month_col = cols[key]
            break

    if month_col is None:
        # try extract month from a date column
        date_col = None
        for key in ['date', 'datetime', 'start_date', 'fire_start_date', 'acq_date', 'ig_date']:
            if key in cols:
                date_col = cols[key]
                break
        if date_col is not None:
            df[date_col] = pd.to_datetime(df[date_col], errors='coerce')
            df['_month'] = df[date_col].dt.month
            month_col = '_month'

    # Identify fire size column
    size_col = None
    for key in ['fire_size', 'size', 'acres', 'burned_acres', 'area', 'area_acres', 'fire_area']:
        if key in cols:
            size_col = cols[key]
            break

    # Identify median wind speed column
    wind_col = None
    for key in ['wind_speed_median', 'median_wind_speed', 'wind_median', 'wind_speed_med', 'wnd_spd_med', 'windmed']:
        if key in cols:
            wind_col = cols[key]
            break

    # Fallback: pick any column containing both 'wind' and 'median'
    if wind_col is None:
        candidates = [c for c in df.columns if ('wind' in c.lower() and 'median' in c.lower())]
        if candidates:
            wind_col = candidates[0]

    out = {
        'month_col': [month_col],
        'size_col': [size_col],
        'wind_col': [wind_col],
        'pearson_r_july': [np.nan],
        'n_july': [0],
        'strong_corr_abs_ge_0_7': [False]
    }

    if month_col is None or size_col is None or wind_col is None:
        return pd.DataFrame(out)

    # Filter to July
    m = df[month_col]
    # handle if month is string like 'July' or 'Jul'
    if pd.api.types.is_numeric_dtype(m):
        july_mask = m == 7
    else:
        s = m.astype(str).str.strip().str.lower()
        july_mask = s.isin(['7', '07', 'jul', 'july'])

    july = df.loc[july_mask, [size_col, wind_col]].copy()

    # numeric coercion
    july[size_col] = pd.to_numeric(july[size_col], errors='coerce')
    july[wind_col] = pd.to_numeric(july[wind_col], errors='coerce')
    july = july.dropna(subset=[size_col, wind_col])

    if len(july) >= 3:
        r = float(july[size_col].corr(july[wind_col], method='pearson'))
        out['pearson_r_july'] = [r]
        out['n_july'] = [int(len(july))]
        out['strong_corr_abs_ge_0_7'] = [bool(abs(r) >= 0.7)]

    return pd.DataFrame(out)
